  "business_unit_id" BIGINT NOT NULL,
  "role" TEXT NOT NULL DEFAULT '*',
  "name" TEXT NOT NULL,
  "metric_key" TEXT NOT NULL,
  "weight" NUMERIC DEFAULT 0,
  "target" NUMERIC DEFAULT 100,
  "direction" TEXT DEFAULT 'Higher Is Better',
  "active" BIGINT DEFAULT 1,
  "created_by" BIGINT,
  "updated_by" BIGINT,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("business_unit_id","role","metric_key")
);

CREATE TABLE bom."performance_reviews" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "business_unit_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "period_type" TEXT DEFAULT 'Monthly',
  "period_start" TEXT NOT NULL,
  "period_end" TEXT NOT NULL,
  "system_score" NUMERIC DEFAULT 0,
  "manager_score" NUMERIC DEFAULT 0,
  "self_score" NUMERIC DEFAULT 0,
  "final_score" NUMERIC DEFAULT 0,
  "status" TEXT DEFAULT 'Draft',
  "self_note" TEXT DEFAULT '',
  "manager_note" TEXT DEFAULT '',
  "reviewed_by" BIGINT,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("user_id","period_type","period_start","period_end")
);

CREATE TABLE bom."pink_fx_customer_allocations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "transaction_id" BIGINT NOT NULL,
  "receipt_id" BIGINT NOT NULL,
  "order_id" BIGINT NOT NULL,
  "amount_krw" NUMERIC NOT NULL,
  "journal_entry_id" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'Active',
  "created_by" BIGINT,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  "reversal_reason" TEXT NOT NULL DEFAULT '',
  "reversed_by" BIGINT,
  "reversed_at" TEXT,
  PRIMARY KEY ("id"),
  CHECK(amount_krw>0),
  UNIQUE ("transaction_id","receipt_id")
);

CREATE TABLE bom."pink_fx_customer_refund_allocations" (
  "transaction_id" BIGINT NOT NULL,
  "receipt_id" BIGINT NOT NULL,
  "amount_krw" NUMERIC NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Active',
  PRIMARY KEY ("transaction_id","receipt_id"),
  CHECK(amount_krw>0),
  CHECK(status IN ('Active','Reversed'))
);

CREATE TABLE bom."pink_fx_fee_debits" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "transaction_id" BIGINT NOT NULL,
  "payment_account_id" BIGINT NOT NULL,
  "currency" TEXT NOT NULL,
  "original_amount" NUMERIC NOT NULL,
  "rate_to_krw" NUMERIC NOT NULL,
  "amount_krw" NUMERIC NOT NULL,
  "reference" TEXT NOT NULL,
  "finance_entry_id" BIGINT,
  "proposal_json" TEXT NOT NULL,
  "payment_date" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Active',
  "created_by" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  CHECK(original_amount>0),
  CHECK(rate_to_krw>0),
  CHECK(amount_krw>0),
  UNIQUE ("finance_entry_id"),
  UNIQUE ("transaction_id")
);

CREATE TABLE bom."pink_fx_history" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "transaction_id" BIGINT,
  "request_id" BIGINT,
  "user_id" BIGINT NOT NULL,
  "action" TEXT NOT NULL,
  "reason" TEXT NOT NULL DEFAULT '',
  "snapshot_json" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);

CREATE TABLE bom."pink_fx_legs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "transaction_id" BIGINT NOT NULL,
  "leg_type" TEXT NOT NULL,
  "currency" TEXT NOT NULL,
  "amount" NUMERIC NOT NULL,
  "account_id" BIGINT,
  "finance_entry_id" BIGINT,
  PRIMARY KEY ("id"),
  CHECK(amount>=0),
  UNIQUE ("transaction_id","leg_type")
);

CREATE TABLE bom."pink_fx_notification_events" (
  "transaction_id" BIGINT NOT NULL,
  "event" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("transaction_id","event","user_id")
);

CREATE TABLE bom."pink_fx_policies" (
  "business_unit_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "approved" BIGINT NOT NULL DEFAULT 0,
  "basis" TEXT NOT NULL DEFAULT 'Invoice carrying value; explicit bank KRW carrying value; realized FX difference; expense evidenced bank fees',
  "decision_note" TEXT NOT NULL DEFAULT '',
  "approved_by" BIGINT,
  "approved_at" TEXT,
  PRIMARY KEY ("business_unit_id")
);

CREATE TABLE bom."pink_fx_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "business_unit_id" BIGINT NOT NULL,
  "created_by" BIGINT NOT NULL,
  "idempotency_key" TEXT NOT NULL,
  "payload_hash" TEXT NOT NULL,
  "payload_json" TEXT NOT NULL,
  "receipt_file" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'Draft',
  "approval_id" BIGINT,
  "transaction_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  "receipt_sha256" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id"),
  CHECK(status IN ('Draft','Pending Approval','Recorded','Reversed')),
  UNIQUE ("business_unit_id","idempotency_key")
);

CREATE TABLE bom."pink_fx_transactions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "request_id" BIGINT NOT NULL,
  "business_unit_id" BIGINT NOT NULL,
  "workflow" TEXT NOT NULL,
  "record_id" BIGINT NOT NULL,
  "counterparty_type" TEXT NOT NULL,
  "counterparty_id" BIGINT NOT NULL,
  "invoice_currency" TEXT NOT NULL,
  "invoice_amount" NUMERIC NOT NULL,
  "invoice_carrying_rate" NUMERIC NOT NULL,
  "allocation_krw" NUMERIC NOT NULL,
  "advance_krw" NUMERIC NOT NULL DEFAULT 0,
  "company_account_id" BIGINT,
  "company_currency" TEXT,
  "company_amount" NUMERIC NOT NULL DEFAULT 0,
  "direction" TEXT NOT NULL,
  "company_rate_to_krw" NUMERIC NOT NULL DEFAULT 1,
  "bank_krw" NUMERIC NOT NULL DEFAULT 0,
  "transfer_currency" TEXT,
  "transfer_amount" NUMERIC NOT NULL DEFAULT 0,
  "recipient_expected" NUMERIC NOT NULL DEFAULT 0,
  "recipient_confirmed" NUMERIC,
  "receiver_account_id" BIGINT,
  "bank_rate" NUMERIC NOT NULL DEFAULT 1,
  "rate_pair" TEXT NOT NULL DEFAULT '',
  "quote_reference" TEXT NOT NULL DEFAULT '',
  "quote_source" TEXT NOT NULL DEFAULT '',
  "quote_time" TEXT NOT NULL DEFAULT '',
  "fee_policy" TEXT NOT NULL DEFAULT 'added_to_debit',
  "source_fee" NUMERIC NOT NULL DEFAULT 0,
  "transfer_fee" NUMERIC NOT NULL DEFAULT 0,
  "fee_krw" NUMERIC NOT NULL DEFAULT 0,
  "fx_difference_krw" NUMERIC NOT NULL DEFAULT 0,
  "payment_date" TEXT NOT NULL,
  "reference" TEXT NOT NULL DEFAULT '',
  "receipt_file" TEXT NOT NULL DEFAULT '',
  "confirmation_status" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'Active',
  "finance_entry_id" BIGINT,
  "projection_table" TEXT,
  "projection_id" BIGINT,
  "proposal_json" TEXT NOT NULL DEFAULT '[]',
  "approval_id" BIGINT,
  "correction_of_id" BIGINT,
  "reversal_reason" TEXT NOT NULL DEFAULT '',
  "created_by" BIGINT NOT NULL,
  "reversed_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'),
  "reversed_at" TEXT,
  "reference_normalized" TEXT NOT NULL DEFAULT '',
  "valuation_basis_json" TEXT NOT NULL DEFAULT '{}',
  "recipient_details_json" TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY ("id"),
  CHECK(invoice_amount>=0),
  CHECK(invoice_carrying_rate>0),
  CHECK(allocation_krw>=0),
  CHECK(advance_krw>=0),
  CHECK(company_amount>=0),
  CHECK(direction IN ('In','Out','NonCash')),
  CHECK(company_rate_to_krw>0),
  CHECK(bank_rate>0),
  CHECK(source_fee>=0),
  CHECK(transfer_fee>=0),
  CHECK(confirmation_status IN ('Confirmed','Reconciled','NonCash')),
  CHECK(status IN ('Active','Reversed')),
  UNIQUE ("finance_entry_id"),
  UNIQUE ("request_id")
);

CREATE TABLE bom."pink_legacy_payment_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "business_unit_id" BIGINT NOT NULL,
