CREATE TABLE bom."pink_receiving_cases" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "business_unit_id" BIGINT NOT NULL,
  "supplier_id" BIGINT NOT NULL,
  "source_type" TEXT NOT NULL,
