  PRIMARY KEY ("id"),
  UNIQUE ("receipt_id")
);

CREATE TABLE bom."pink_receiving_lines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "receipt_id" BIGINT NOT NULL,
  "source_line_id" BIGINT NOT NULL,
  "snapshot_json" TEXT NOT NULL,
  "expected_q" BIGINT NOT NULL,
  "physical_q" BIGINT NOT NULL,
  "fulfillment_q" BIGINT NOT NULL,
  "accepted_q" BIGINT NOT NULL,
  "quarantine_q" BIGINT NOT NULL,
  "rejected_q" BIGINT NOT NULL,
  "expected_bags" BIGINT,
  "actual_bags" BIGINT,
  "quality" TEXT NOT NULL,
  "remarks" TEXT NOT NULL DEFAULT '',
  "discrepancies_json" TEXT NOT NULL DEFAULT '[]',
  "legacy_id" BIGINT,
  PRIMARY KEY ("id"),
  CHECK(expected_q>=0),
  CHECK(physical_q>=0),
  CHECK(fulfillment_q>=0),
  CHECK(accepted_q>=0),
  CHECK(quarantine_q>=0),
  CHECK(rejected_q>=0),
  CHECK(expected_bags>=0),
  CHECK(actual_bags>=0),
  CHECK(physical_q=accepted_q+quarantine_q+rejected_q),
  UNIQUE ("receipt_id","source_line_id")
);

